func (b BlockStartBinding) EarliestPlannedBlockStartForClass(ctx context.Context, schoolClass string, date calendar.Date) (string, error) {
	start, err := b.Starts.EarliestPlannedBlockStartForClass(ctx, schoolClass, date)
	if err != nil {
		return "", MapArrivalExceptionError(err)
	}
	return start, nil
}

func (b CallerBinding) CurrentStaffID(ctx context.Context) (int64, error) {
	staffID, found, err := b.CallerReader.CurrentStaffID(ctx)
	switch {
	case err != nil:
		return 0, err
	case !found:
		return 0, classday.ErrStaffRecordRequired
	}
	return staffID, nil
}

func (b CareDayBinding) ResolveForDate(ctx context.Context, studentIDs []int64, date calendar.Date) (map[int64]ports.CareDay, error) {
	verdicts, err := b.Resolver.ResolveForDate(ctx, studentIDs, date)
	if err != nil {
		return nil, err
	}
	out := make(map[int64]ports.CareDay, len(verdicts))
	for studentID, verdict := range verdicts {
		out[studentID] = ports.CareDay(verdict)
	}
	return out, nil
}

func (b ClassArrivalExceptionBinding) DeleteClassArrivalException(ctx context.Context, schoolClass string, date calendar.Date) error {
	return MapArrivalExceptionError(b.Store.DeleteClassArrivalException(ctx, schoolClass, date))
}

func (b ClassArrivalExceptionBinding) ListClassArrivalExceptions(ctx context.Context, schoolClass string, from, to calendar.Date) ([]ClassArrivalException, error) {
	rows, err := b.Store.ListClassArrivalExceptions(ctx, schoolClass, from, to)
	if err != nil {
		return nil, MapArrivalExceptionError(err)
	}
	out := make([]ClassArrivalException, 0, len(rows))
	for _, row := range rows {
		if row != nil {
			out = append(out, mapClassArrivalException(row))
		}
	}
	return out, nil
}

func (b ClassArrivalExceptionBinding) UpsertClassArrivalException(ctx context.Context, in ClassArrivalExceptionWrite) (ClassArrivalException, error) {
	row, err := b.Store.UpsertClassArrivalException(ctx, careplan.ClassArrivalExceptionInput{SchoolClass: in.SchoolClass, Date: in.Date, ArrivalTime: in.ArrivalTime, Reason: in.Reason, Origin: in.Origin}, in.CreatedBy)
	if err != nil {
		return ClassArrivalException{}, MapArrivalExceptionError(err)
	}
	return mapClassArrivalException(row), nil
}

func (b EffectiveTimeBinding) ArrivalTimes(ctx context.Context, studentIDs []int64, date calendar.Date) (map[int64]*time.Time, error) {
	effective, err := b.Arrivals.GetBulkEffectiveArrivalTimesForDate(ctx, studentIDs, date)
	if err != nil {
		return nil, err
	}
	out := make(map[int64]*time.Time, len(effective))
	for studentID, entry := range effective {
		if entry != nil {
			out[studentID] = entry.ArrivalTime
		}
	}
	return out, nil
}

func (b EffectiveTimeBinding) PickupTimes(ctx context.Context, studentIDs []int64, date calendar.Date) (map[int64]*time.Time, error) {
	effective, err := b.Pickups.GetBulkEffectivePickupTimesForDate(ctx, studentIDs, date)
	if err != nil {
		return nil, err
	}
	out := make(map[int64]*time.Time, len(effective))
	for studentID, entry := range effective {
		if entry != nil {
			out[studentID] = entry.PickupTime
		}
	}
	return out, nil
}

func (e MappedError) Error() string {
	return e.err.Error()
}

func (b PickupBaselineBinding) RegularPickupTimes(ctx context.Context, studentIDs []int64, date calendar.Date) (map[int64]string, error) {
	projection, err := b.Baselines.Project(ctx, studentIDs, date, date)
	if err != nil {
		return nil, err
	}
	out := make(map[int64]string, len(studentIDs))
	for _, studentID := range studentIDs {
		if row := projection.ForDate(studentID, date); row != nil {
			out[studentID] = row.PickupTime.Format("15:04")
		}
	}
	return out, nil
}

func (a arrivalExceptions) ClearArrivalException(ctx context.Context, schoolClass string, date classday.Date) error {
	if a.schedule == nil {
		return classday.ErrArrivalExceptionsNotConfigured
	}
	day, err := parseDate(date)
	if err != nil {
		return err
	}
	if err := a.schedule.DeleteClassArrivalException(ctx, schoolClass, day); err != nil {
		return err
	}
	a.announce(ctx)
	return nil
}

func (a arrivalExceptions) EarliestBlockStart(ctx context.Context, schoolClass string, date classday.Date) (string, error) {
	if a.schedule == nil {
		return "", classday.ErrArrivalExceptionsNotConfigured
	}
	day, err := parseDate(date)
	if err != nil {
		return "", err
	}
	if a.blockStarts == nil {
		return "", errors.New("class day arrival exceptions: block starts not configured")
	}
	return a.blockStarts.EarliestPlannedBlockStartForClass(ctx, schoolClass, day)
}

func (a arrivalExceptions) MayWriteArrivalExceptions(ctx context.Context) (bool, error) {
	if a.schedule == nil {
		return false, classday.ErrArrivalExceptionsNotConfigured
	}
	if a.writeScope == nil {
		return false, errors.New("class day arrival exceptions: settings not configured")
	}
	may, err := a.writeScope.SchoolMayWriteClassArrivalExceptions(ctx)
	if err != nil {
		return false, fmt.Errorf("class day arrival exceptions: resolve school portal write scope: %w", err)
	}
	return may, nil
}

func (s *classDayService) ResolveClass(ctx context.Context, requested string) (string, error) {
	assigned, err := s.caller.GetMySchoolClasses(ctx)
	if err != nil {
		return "", err
	}
	return resolveRequestedClass(requested, assigned)
}
